#include "kstationNativeController.h"
#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <new>
#include <vector>
namespace {bool watch=false;unsigned allocations=0;void check(bool p,const char*m){if(!p)throw std::runtime_error(m);}}
void*operator new(size_t n){if(watch)++allocations;if(auto*p=std::malloc(n?n:1))return p;throw std::bad_alloc();}void*operator new[](size_t n){return ::operator new(n);}void operator delete(void*p)noexcept{std::free(p);}void operator delete[](void*p)noexcept{std::free(p);}void operator delete(void*p,size_t)noexcept{std::free(p);}void operator delete[](void*p,size_t)noexcept{std::free(p);}
int main(int argc,char**argv){try{if(argc!=2)return 77;std::ifstream in(argv[1],std::ios::binary);std::vector<uint8_t>image{std::istreambuf_iterator<char>(in),{}};kstation::NativeController native(image,{[](uint32_t){return uint8_t(7);},[](uint32_t,uint8_t){return true;},[](bool){}});check(native.isNative(),"Native backend identity");check(!native.exec(0),"Zero budget consumed clocks");bool rejected=false;try{(void)native.core();}catch(const std::logic_error&){rejected=true;}check(rejected,"Native backend exposed architectural CPU");watch=true;for(unsigned i=0;i<1000;++i)check(native.exec(128)>=128,"Native early boot made no progress");watch=false;check(!allocations,"Native early processing allocated");auto first=native.debugState();check(first.instructions&&first.interpretedSteps==0&&!first.mainEntered&&!native.bootReady(),"Early boot state");native.reset();check(native.debugState().cycles==0,"Independent full reset");watch=true;for(unsigned i=0;i<1000;++i)native.exec(128);watch=false;auto second=native.debugState();check(first.cycles==second.cycles&&first.instructions==second.instructions&&!allocations,"Native reset determinism");std::printf("{\"passed\":true,\"early_boot_cycles\":%llu,\"early_boot_phases\":%llu,\"reset_exact\":true,\"linked_h8_sources\":false,\"processing_allocations\":%u,\"full_boot_proven\":false}\n",first.cycles,first.instructions,allocations);return 0;}catch(const std::exception&e){watch=false;std::fprintf(stderr,"FAIL:%s\n",e.what());return 1;}}
